import 'package:flutter/material.dart';
import 'login_screen.dart';
class OnboardingScreen extends StatefulWidget { const OnboardingScreen({super.key}); @override State<OnboardingScreen> createState() => _OnboardingScreenState(); }
class _OnboardingScreenState extends State<OnboardingScreen> {
  int _p = 0; final _data = [['동네 친구', '나와 가까운 곳에 있는\n새로운 인연을 찾아보세요', Icons.people], ['여행 모임', '함께 여행 갈 친구를 찾고\n안전하게 동행하세요', Icons.travel_explore], ['하트 시그널', '여행 중 미션을 수행하며\n마음에 드는 사람에게 투표하세요', Icons.favorite]];
  @override Widget build(BuildContext context) => Scaffold(backgroundColor: Colors.white, body: SafeArea(child: Column(children: [Expanded(child: PageView.builder(onPageChanged: (i) => setState(() => _p = i), itemCount: _data.length, itemBuilder: (_, i) => Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(_data[i][2] as IconData, size: 100, color: const Color(0xFFFF3B30)), const SizedBox(height: 48), Text(_data[i][0] as String, style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)), const SizedBox(height: 16), Text(_data[i][1] as String, textAlign: TextAlign.center, style: const TextStyle(fontSize: 16, color: Colors.grey, height: 1.5))]))), Row(mainAxisAlignment: MainAxisAlignment.center, children: List.generate(_data.length, (i) => Container(margin: const EdgeInsets.symmetric(horizontal: 4), width: _p == i ? 24 : 8, height: 8, decoration: BoxDecoration(color: _p == i ? const Color(0xFFFF3B30) : Colors.grey.shade300, borderRadius: BorderRadius.circular(4))))), const SizedBox(height: 48), Padding(padding: const EdgeInsets.all(24), child: ElevatedButton(onPressed: () { if (_p < _data.length - 1) setState(() => _p++); else Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const LoginScreen())); }, style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFFFF3B30), minimumSize: const Size(double.infinity, 56), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16))), child: Text(_p == _data.length - 1 ? '시작하기' : '다음', style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16))))])));
